/* KINTO V93 — shared bundle details + printable PDF invoice renderer. */
(()=>{'use strict';
const SUPABASE_URL='https://hsmmbloouskqdnptiiad.supabase.co',SUPABASE_KEY='sb_publishable_6_IDhNRdtxboDuCfBeAulQ_RRrBqpFH';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function details(order){const raw=order?.details;if(!raw)return{};if(typeof raw==='object')return raw;try{return JSON.parse(raw)}catch{return{}}}
function items(order){const d=details(order);if(Array.isArray(d.items)&&d.items.length)return d.items;return[{product_name:d.product_name||order?.product_name||order?.name||'المنتج',product_image:d.product_image||order?.image_url||'',selected_options:{color:d.color||'',size:d.size||'',volume:d.volume||''},quantity:Number(d.quantity??order?.quantity??1)||1,unit_price_local:Number(d.unit_price_local??order?._unit_price??order?.total_price??0)||0,line_total_local:Number(order?.total_price??0)||0,currency:order?.currency||d.local_currency||'IQD'}]}
function money(v,c){const n=Number(v);return `${Number.isFinite(n)?n.toLocaleString('en-US',{maximumFractionDigits:2}):'0'} ${esc(c||'IQD')}`}
function first(...xs){for(const x of xs){if(x!==null&&x!==undefined&&String(x).trim())return String(x).trim()}return''}
function customerData(order){const d=details(order),c=order?._kintoCustomer||((d.customer&&typeof d.customer==='object')?d.customer:{});return{name:first(c.name,order?.customer_name,d.customer_name),phone:first(c.phone,order?._customer_phone,order?.customer_phone,d.customer_phone),secondary:first(c.secondary_phone,c.phone2,c.alt_phone,order?._secondary_phone,order?.secondary_phone,d.secondary_phone,d.customer_secondary_phone),country:first(c.country,c.country_name,order?.country,d.country,d.customer_country),province:first(c.province,c.governorate,c.state,c.city,order?.province,order?.governorate,order?.state,order?.city,d.province,d.governorate,d.state,d.city,d.customer_province,d.customer_governorate),address:first(c.address,c.address_details,c.full_address,c.delivery_address,order?.address,order?.address_details,order?.delivery_address,d.address,d.address_details,d.full_address,d.delivery_address,d.customer_address)}}
async function hydrateCustomer(order){if(!order?.customer_id||order._kintoCustomerLoaded)return order?._kintoCustomer||null;order._kintoCustomerLoaded=true;try{const r=await fetch(`${SUPABASE_URL}/rest/v1/customers?select=*&id=eq.${encodeURIComponent(order.customer_id)}&limit=1`,{cache:'no-store',headers:{apikey:SUPABASE_KEY,Authorization:`Bearer ${SUPABASE_KEY}`,Accept:'application/json'}});if(r.ok){const rows=await r.json();order._kintoCustomer=Array.isArray(rows)?rows[0]||null:null}}catch(e){console.warn('KINTO customer hydration failed',e)}return order._kintoCustomer||null}
function bundleHtml(order){const list=items(order),currency=order?.currency||details(order).local_currency||list[0]?.currency||'IQD';return `<section class="kinto-v93-bundle"><h3>منتجات الطلب (${list.length})</h3><div class="kinto-v93-items">${list.map((x,i)=>{const o=x.selected_options||{},q=Math.max(1,Number(x.quantity)||1),unit=Number(x.unit_price_local)||0,line=Number(x.line_total_local)||unit*q;return `<article class="kinto-v93-item">${x.product_image?`<img src="${esc(x.product_image)}" alt="">`:''}<div><b>${i+1}. ${esc(x.product_name||'المنتج')}</b><div class="kinto-v93-meta">${o.color?`اللون: ${esc(o.color)} · `:''}${o.size?`المقاس: ${esc(o.size)} · `:''}${o.volume?`الحجم: ${esc(o.volume)} · `:''}الكمية: ${q}</div><div class="kinto-v93-price">${money(unit,x.currency||currency)} × ${q} = <b>${money(line,x.currency||currency)}</b></div></div></article>`}).join('')}</div></section>`}
function totals(order){const d=details(order),goods=Number(d.customer_total_local??order?.total_price??0)||0,external=Number(order?.external_shipping_fee??d.external_shipping_fee??d.shipping_fee??0)||0,delivery=Number(order?.delivery_fee??d.delivery_fee??d.local_delivery_fee??0)||0;return{goods,external,delivery,grand:goods+external+delivery,currency:order?.currency||d.local_currency||'IQD'}}
function englishDate(value){if(!value)return'---';const x=new Date(value);if(Number.isNaN(x.getTime()))return'---';return new Intl.DateTimeFormat('en-GB',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',second:'2-digit',hour12:false}).format(x).replace(',','')}
function normalizeCode(order){const raw=first(order?.order_code,details(order).bundle_id,order?.id,'---');const m=raw.match(/KN[-\s]?([0-9]{1,12})/i);return m?`KN-${m[1].padStart(6,'0')}`:raw}
function repairNativeDetails(container,order){if(!container)return;[...container.querySelectorAll('.detail-box,div,p,li')].forEach(el=>{const txt=(el.textContent||'').trim();if(/^سعر القطعة\s*:/i.test(txt))el.remove()});const c=customerData(order),province=c.province||'غير محددة';[...container.querySelectorAll('.detail-box,div,p,li')].forEach(el=>{const txt=(el.textContent||'').trim();if(/^المحافظة\s*:/i.test(txt)&&el.children.length<=1)el.innerHTML=`<b>المحافظة:</b> ${esc(province)}`})}
async function invoice(order){await hydrateCustomer(order);const d=details(order),t=totals(order),code=normalizeCode(order),date=englishDate(order?.created_at||d.submitted_at),c=customerData(order),rows=items(order).map((x,i)=>{const q=Math.max(1,Number(x.quantity)||1),u=Number(x.unit_price_local)||0,l=Number(x.line_total_local)||u*q,o=x.selected_options||{};return `<tr><td>${i+1}</td><td>${x.product_image?`<img src="${esc(x.product_image)}">`:''}</td><td><b>${esc(x.product_name||'المنتج')}</b><small>${[o.color&&'اللون: '+o.color,o.size&&'المقاس: '+o.size,o.volume&&'الحجم: '+o.volume].filter(Boolean).map(esc).join(' · ')}</small></td><td>${q}</td><td>${money(u,x.currency||t.currency)}</td><td>${money(l,x.currency||t.currency)}</td></tr>`}).join('');const w=window.open('','_blank','width=980,height=760');if(!w)return alert('يرجى السماح بالنوافذ المنبثقة لطباعة الفاتورة.');w.document.write(`<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><title>KINTO Invoice ${esc(code)}</title><style>@page{size:A4;margin:12mm;-webkit-print-color-adjust:exact;print-color-adjust:exact}*{box-sizing:border-box;-webkit-print-color-adjust:exact;print-color-adjust:exact}body{font-family:Tahoma,Arial,sans-serif;color:#13231d;margin:0;background:#fff}.invoice{max-width:190mm;margin:auto;min-height:270mm;display:flex;flex-direction:column}.head{display:grid;grid-template-columns:1fr 1fr 1fr;align-items:center;border-bottom:3px solid #ff7a00;padding-bottom:14px}.brand{display:flex;align-items:center;gap:12px;justify-self:start}.brandmark{width:72px;height:72px;border-radius:50%;background:#063b2d!important;color:#ff7a00!important;display:grid;place-items:center;font:900 44px Arial;box-shadow:inset 0 0 0 1px #063b2d}.brand h1{margin:0;color:#063b2d}.order-center{text-align:center;justify-self:center}.order-center b{font-size:20px;letter-spacing:1px}.barcode-bars{height:34px;width:170px;margin:6px auto;background:repeating-linear-gradient(90deg,#111 0 2px,transparent 2px 4px,#111 4px 5px,transparent 5px 8px)!important}.date{text-align:left;direction:ltr;justify-self:end}.muted{color:#64748b;font-size:12px}.meta{margin:18px 0;display:grid;grid-template-columns:1fr 1fr;gap:8px}.box{border:1px solid #dbe5e0;border-radius:9px;padding:10px}table{width:100%;border-collapse:collapse}th,td{border-bottom:1px solid #dbe5e0;padding:9px;text-align:center}th{background:#063b2d!important;color:#fff!important}td img{width:48px;height:48px;object-fit:contain;border-radius:7px;background:transparent}small{display:block;color:#64748b;margin-top:4px}.invoice-bottom{margin-top:auto;display:grid;grid-template-columns:1fr 1fr;gap:22px;align-items:end}.customer-card{border:1px solid #dbe5e0;border-radius:10px;padding:12px;line-height:1.8;text-align:right}.customer-card h3{margin:0 0 6px;color:#063b2d}.totals{width:100%}.totals div{display:flex;justify-content:space-between;padding:8px;border-bottom:1px solid #e5e7eb}.totals .grand{font-size:17px;font-weight:900;color:#063b2d;border-top:2px solid #ff7a00}.actions{text-align:center;margin:20px}.actions button{background:#063b2d;color:#fff;border:0;border-radius:9px;padding:11px 18px;font-weight:800;cursor:pointer}@media print{.actions{display:none}.brandmark,.barcode-bars,th{print-color-adjust:exact!important;-webkit-print-color-adjust:exact!important}}</style></head><body><main class="invoice"><header class="head"><div class="brand"><div class="brandmark">K</div><div><h1>KINTO</h1><div class="muted">Official Invoice</div></div></div><div class="order-center"><div class="muted">Sipariş No</div><b>${esc(code)}</b><div class="barcode-bars" aria-hidden="true"></div></div><div class="date"><b>Date / Time</b><div>${esc(date)}</div></div></header><section class="meta"><div class="box"><b>الحالة:</b> ${esc(order?.status||'---')}</div><div class="box"><b>المتجر:</b> ${esc(d.store_name||'---')}</div></section><table><thead><tr><th>#</th><th>الصورة</th><th>المنتج / الخيارات</th><th>الكمية</th><th>سعر الوحدة</th><th>الإجمالي</th></tr></thead><tbody>${rows}</tbody></table><section class="invoice-bottom"><div class="customer-card"><h3>معلومات العميل</h3><div><b>الاسم:</b> ${esc(c.name||'---')}</div><div><b>الهاتف الأساسي:</b> <span dir="ltr">${esc(c.phone||'---')}</span></div><div><b>الهاتف الاحتياطي:</b> <span dir="ltr">${esc(c.secondary||'---')}</span></div><div><b>الدولة:</b> ${esc(c.country||'---')}</div><div><b>المحافظة:</b> ${esc(c.province||'---')}</div><div><b>العنوان:</b> ${esc(c.address||'---')}</div></div><div class="totals"><div><span>مجموع السلع</span><b>${money(t.goods,t.currency)}</b></div><div><span>الشحن الخارجي</span><b>${money(t.external,t.currency)}</b></div><div><span>التوصيل الداخلي</span><b>${money(t.delivery,t.currency)}</b></div><div class="grand"><span>المجموع الكلي</span><b>${money(t.grand,t.currency)}</b></div></div></section><div class="actions"><button onclick="print()">تحميل / طباعة الفاتورة PDF</button></div></main></body></html>`);w.document.close();return w}
async function enhance(container,order,{invoiceButton=true}={}){if(!container||!order)return;container.querySelector('.kinto-v93-bundle')?.remove();container.querySelector('.kinto-v93-invoice-btn')?.remove();repairNativeDetails(container,order);container.insertAdjacentHTML('beforeend',bundleHtml(order));await hydrateCustomer(order);repairNativeDetails(container,order);if(invoiceButton){const b=document.createElement('button');b.type='button';b.className='kinto-v93-invoice-btn';b.textContent='تحميل / طباعة الفاتورة PDF';b.style.cssText='margin-top:14px;background:#063b2d;color:#fff;border:1px solid #ff7a00;border-radius:9px;padding:10px 14px;font-weight:800;cursor:pointer';b.onclick=()=>invoice(order);container.appendChild(b)}}
const style=document.createElement('style');style.textContent='.kinto-v93-bundle{margin-top:16px;border-top:1px solid rgba(148,163,184,.25);padding-top:12px}.kinto-v93-items{display:grid;gap:9px}.kinto-v93-item{display:grid;grid-template-columns:64px 1fr;gap:10px;align-items:center;border:1px solid rgba(148,163,184,.22);border-radius:10px;padding:9px}.kinto-v93-item img{width:64px;height:64px;object-fit:contain;border-radius:8px;background:transparent}.kinto-v93-meta{font-size:12px;opacity:.78;margin-top:4px}.kinto-v93-price{font-size:12px;margin-top:5px}';document.head.appendChild(style);
window.KintoBundleV93={details,items,bundleHtml,enhance,printInvoice:invoice,totals,customerData,hydrateCustomer};
})();